using System.Security.Principal;
using Microsoft.Extensions.Logging.Console;
using Microsoft.Extensions.Options;
using TuoiTho.SessionAgent;
var builder=Host.CreateApplicationBuilder(args);builder.Logging.ClearProviders();builder.Logging.AddJsonConsole(options=>{options.IncludeScopes=true;options.TimestampFormat="yyyy-MM-ddTHH:mm:ss.fffzzz";});builder.Services.Configure<SessionAgentOptions>(builder.Configuration.GetSection(SessionAgentOptions.SectionName));builder.Services.AddSingleton(TimeProvider.System);builder.Services.AddSingleton<IChildWarningSink,DialogWarningSink>();builder.Services.AddSingleton<IRawInputActivityTracker,RawInputActivityTracker>();builder.Services.AddSingleton<IWindowsIdleTimeDiagnostics,WindowsIdleTimeDiagnostics>();builder.Services.AddSingleton<IInteractiveActivitySampler,InteractiveActivitySampler>();builder.Services.AddSingleton<LocalActivityReporter>();builder.Services.AddSingleton<LocalWarningListener>(s=>{var o=s.GetRequiredService<IOptions<SessionAgentOptions>>().Value;SecurityIdentifier? publisher=null;if(o.M1TestMode&&!string.IsNullOrWhiteSpace(o.M1WarningPublisherSid))publisher=new SecurityIdentifier(o.M1WarningPublisherSid);return new LocalWarningListener(o.ProfileId,System.Diagnostics.Process.GetCurrentProcess().SessionId,s.GetRequiredService<IChildWarningSink>(),s.GetRequiredService<ILogger<LocalWarningListener>>(),publisher);});builder.Services.AddHostedService<Worker>();using var host=builder.Build();host.Run();